/**
 * Helpers for handling arrays.
 */
export declare class Arrays {
    /**
     * Takes in an array or string or null and always returns an array.
     * If the incoming value is a string, splits it by commas. This is especaially useful for HTML attributes.
     * Note that null (or other falsy objects) are returned as an empty array.
     *
     * @param arrayCandidate - A string array or string that is split by comma.
     */
    static assureArray(arrayCandidate: string | string[]): string[];
    /**
     * Calculates a sum of array items.
     * Null items will be added as zero.
     * @param array Array to sum
     * @param selector Selector for a number to sum.
     */
    static sum<T>(array: T[], selector: (item: T) => number): number;
    /**
     * Sequence generator function gets an array between two numbers (inclusive).
     * (commonly referred to as "range", e.g. Clojure, PHP etc)
     * @param start Start number of the sequence
     * @param stop End number of the sequence
     * @param step Step between the numbers, default is 1.
     * @example
     * Arrays.getRange(2019, 2023);
     * // [2019, 2020, 2021, 2022, 2023]
     */
    static getRange(start: number, stop: number, step?: number): number[];
    /**
     * Does a group-by of an array of objects with given key.
     * @param source The source array.
     * @param selector Selector for the key in the array.
     * @returns An object that is the array grouped by the keys.
     */
    static groupBy<T>(source: T[], selector: (x: T) => string | undefined | null): ({
        [key: string]: T[];
    });
    /**
     * Returns distinct elements from an array based on a selector function.
     * @param source The source array to filter
     * @param selector Function to select the key to compare for uniqueness
     * @returns Array with duplicate elements removed
     */
    static distinct<T>(source: T[], selector: (x: T) => string): T[];
    /** Moves an item of given index one position up or down in the array */
    static moveItem<T>(array: T[], index: number, direction: "up" | "down"): void;
    private static moveItemInArray;
}

